const revokeRecoveryCodes = `-- name: RevokeRecoveryCodes :one

WITH revoked AS (
    UPDATE mfa_recovery_codes SET revoked_at = $1
    WHERE user_id = $2 AND revoked_at IS NULL
    RETURNING used_at
)
SELECT (count(*) FILTER (WHERE used_at IS NULL))::int AS usable FROM revoked
`

type RevokeRecoveryCodesParams struct {
	Now    pgtype.Timestamptz `json:"now"`
	UserID uuid.UUID          `json:"user_id"`
}

// ---- recovery codes ----
// Revokes every unrevoked code and reports how many of them were still usable.
func (q *Queries) RevokeRecoveryCodes(ctx context.Context, arg RevokeRecoveryCodesParams) (int32, error) {
	row := q.db.QueryRow(ctx, revokeRecoveryCodes, arg.Now, arg.UserID)
	var usable int32
	err := row.Scan(&usable)
	return usable, err
}

